 play(i,id,suit){if(this.ended||this.pending||i!==this.turn)throw Error('Turno non valido');let h=this.players[i].hand,k=h.findIndex(c=>c.id===id),c=h[k];if(!c||!this.legal(c))throw Error('Carta non valida');if(c.v===9&&![0,1,2,3].includes(suit))throw Error('Scegli il palo');this.drawnPlayable=false;this.turnDeadline=0;h.splice(k,1);this.discard.push(c);this.suit=c.v===9?suit:c.s;if(c.v===2)this.penalty+=2;let calls=[];if(c.v===10)calls.push('CHIODO');if(h.length===1)calls.push('SOLA');this.pending={i,c,calls,called:[]};this.message=this.players[i].name+' gioca '+c.v;if(!calls.length)this.resolve([]);return calls;}
