function chSettings(root){const dlg=document.createElement('div');dlg.className='ch-settings';dlg.innerHTML='<div class="ch-settings-panel"><h2>Impostazioni CHIODO</h2><label>Ambientazione<select data-pref="theme"><option value="royal">Classic Royal</option><option value="gold">Black &amp; Gold</option><option value="ocean">Ocean Blue</option><option value="napoli">Napoli Prestige</option><option value="palazzo">Palazzo Reale</option><option value="sunset">Napoli Sunset</option><option value="diamond">Royal Diamond</option><option value="antica">Antica Napoli</option></select></label><label>Qualità grafica<select data-pref="quality"><option value="low">Bassa</option><option value="medium">Media</option><option value="high">Alta</option><option value="ultra">Ultra</option></select></label><label>Avatar<select data-pref="avatar"><option value="0">Classico</option><option value="1">Prestige</option><option value="2">Sport</option><option value="3">Royal</option></select></label><label>Suoni<input type="checkbox" data-pref="sound"></label><label>Vibrazione<input type="checkbox" data-pref="vibration"></label><button class="ch-btn">Fatto</button></div>';root.appendChild(dlg);dlg.querySelectorAll('[data-pref]').forEach(x=>{const k=x.dataset.pref;if(x.type==='checkbox')x.checked=chPrefs[k];else x.value=chPrefs[k];x.onchange=()=>{chPrefs[k]=x.type==='checkbox'?x.checked:x.value;chSave();chApply(root);if(root._chState){const st=root._chState;const cv=root._chCanvas;if(global.NC65_CHIODO_SCENE){chScene(root,st,[],0,false);}else if(chPrefs.quality==='low'){root._chFrameKey=(root._chFrameKey||0)+1;cv?.remove();root.querySelector('.ch-arena')?.classList.remove('ch-rendered');}else chScene(root,st,[],0,false);}};});dlg.querySelector('button').onclick=()=>dlg.remove();}
